-- Walkthrough: Build an agency website.
--
-- A third walkthrough, for someone building an agency site for themselves or
-- for a client. Eight steps, each ending in a file saved to a spec folder
-- that the next step's prompts read: brief, blueprint, copy, design system,
-- behaviour, forms and content, build, launch and handover.
insert into wizards (title, slug, kind, reusable, role_level, status, steps) values
(
  'Build an agency website',
  'build-an-agency-website',
  'wizard',
  false,
  'intermediate',
  'published',
  '[{"key":"brief","title":"Brief","intro":"Write down who the site is for and what it should make them do. Everything after this reads from it.","blocks":[{"kind":"text","body":"An agency website has one job: turn the right visitor into an enquiry. Most of them go wrong before any design happens, because nobody wrote down who the site is for, what is being sold, and what a visitor should do next.\n\nThis walkthrough gets those decisions on paper first, then turns them into a finished site one file at a time. It works whether the agency is yours or a client''s."},{"kind":"text","body":"How it works:\n\n1. Make a folder on your computer called spec.\n2. Each step ends with one file saved in that folder: brief.md, blueprint.md, copy.md and so on.\n3. Each prompt asks you to paste in the files that came before it. That way your AI tool works from your decisions and does not guess.\n\nKeep the whole thing in one project or one long chat, in Claude or whichever AI tool you prefer."},{"kind":"callout","tone":"info","body":"Never put a site live before? Do Ship your first web project first. This walkthrough assumes you know how to get a page onto the internet, and spends its time on what goes on the page."},{"kind":"links","links":[{"label":"Ship your first web project","href":"/walkthroughs/ship-your-first-web-project"}]},{"kind":"tabs","label":"Whose site is it?","tabs":[{"key":"mine","title":"My own agency","blocks":[{"kind":"text","body":"You are the client, which is harder than it sounds. The trap is describing yourself the way you see the work (\"full-service digital studio\") and not the way a buyer looks for it (\"someone to rebuild our Shopify store before November\").\n\nBefore you write the brief, answer three things out loud: who was your best client so far, what did you fix for them, and what did they nearly not hire you over."}]},{"key":"client","title":"A client''s agency","blocks":[{"kind":"text","body":"Get the answers from the client, on a call, before you open any tool. Leave the call with real things, not opinions: the logo and brand colours, two or three finished projects with numbers, testimonials they have permission to use, the name of the one person who signs off, and the deadline."},{"kind":"prompt","label":"Paste this into your AI tool before the call","prompt":"I build websites and I am about to have a first call with a new client. They run an agency and want a new website.\n\nWhat I know so far: [paste their email, their current site address, anything else]\n\nWrite me the questions for a 30 minute discovery call, in the order I should ask them. Cover: who their best clients are, what they sell and for how much, what a good enquiry looks like, what proof they can show, what they dislike about the current site, who approves the work, and the deadline and budget.\n\nKeep it to 12 questions at most. For each one, add a short note on what a vague answer sounds like and the follow-up that gets a real one."}]}]},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Help me write a one-page brief for an agency website. Ask me nothing yet, work from what is below, and mark anything you had to assume with [ASSUMED] so I can correct it.\n\nThe agency: [name, what it does, where it is based]\nWhose site this is: [my own agency, or a client''s]\nBest-fit client: [who buys, their size, what is going wrong for them when they come looking]\nServices and rough prices: [list them]\nThe one action a visitor should take: [book a call, send an enquiry, ask for a quote]\nReal proof we can show: [finished projects, results with numbers, testimonials we have permission to use]\nWhat makes us different from the two or three agencies we lose work to: [be honest]\nTone of voice: [three words]\nDeadline and anything fixed: [existing logo, colours, domain, platform]\n\nWrite the brief with these headings: Audience, Offer, Primary action, Proof, Positioning in one sentence, Tone, Constraints, Out of scope for version one.\n\nKeep it under 400 words. Finish with the three weakest parts of the brief and what I would need to find out to fix each.","prompts":[{"title":"Write the brief","prompt":"Help me write a one-page brief for an agency website. Ask me nothing yet, work from what is below, and mark anything you had to assume with [ASSUMED] so I can correct it.\n\nThe agency: [name, what it does, where it is based]\nWhose site this is: [my own agency, or a client''s]\nBest-fit client: [who buys, their size, what is going wrong for them when they come looking]\nServices and rough prices: [list them]\nThe one action a visitor should take: [book a call, send an enquiry, ask for a quote]\nReal proof we can show: [finished projects, results with numbers, testimonials we have permission to use]\nWhat makes us different from the two or three agencies we lose work to: [be honest]\nTone of voice: [three words]\nDeadline and anything fixed: [existing logo, colours, domain, platform]\n\nWrite the brief with these headings: Audience, Offer, Primary action, Proof, Positioning in one sentence, Tone, Constraints, Out of scope for version one.\n\nKeep it under 400 words. Finish with the three weakest parts of the brief and what I would need to find out to fix each."},{"title":"Challenge my brief","prompt":"Here is the brief for an agency website:\n\n[paste brief.md]\n\nRead it as the buyer it describes, someone comparing three agencies in one afternoon. Tell me:\n1. Which sentences could appear on any agency site and so say nothing\n2. What the buyer would still not know after reading it\n3. Whether the proof listed actually supports the positioning\n\nThen rewrite only the positioning sentence, three ways, each more specific than mine."}]},{"kind":"callout","tone":"warning","body":"Use real proof only. Collect the client names, results and testimonials you are allowed to publish now, while you are thinking about it. If you do not have a number, do not let your AI tool supply one. An invented statistic or a made-up testimonial on an agency site is the fastest way to lose the client who checks."},{"kind":"checklist","tasks":[{"id":"agency-brief-folder","label":"Made a spec folder for this project"},{"id":"agency-brief-saved","label":"Saved the brief as brief.md"},{"id":"agency-brief-proof","label":"Listed the real projects and testimonials I can publish"}]}]},{"key":"blueprint","title":"Blueprint","intro":"Decide which pages exist, what each one is for, and how a visitor gets from landing to enquiring.","blocks":[{"kind":"text","body":"The blueprint is the list of pages, what sits on each one from top to bottom, and the route a visitor takes through them. It is the cheapest place to change your mind: moving a section here is one line of text, and moving it after the build is an afternoon."},{"kind":"callout","tone":"tip","body":"Smaller is better. Most agency sites need Home, Work, one page per case study, Services, About and Contact. Every extra page is another page to write, design, build and keep up to date. If a page has no job in getting someone to enquire, leave it for version two."},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Plan the structure of an agency website from this brief:\n\n[paste brief.md]\n\nGive me four things.\n\n1. Site map. Every page, its address (for example /work/client-name), and its one job in a single sentence. Suggest the smallest set of pages that does the brief justice.\n\n2. Visitor journeys. The three most likely ways someone arrives (for example a referral who types the name, a search for the service, a link to one case study), and for each, the pages they see in order and the moment they would enquire.\n\n3. Sections per page. For every page, the sections from top to bottom. For each section, say what question in the visitor''s head it answers. If a section answers no question, remove it.\n\n4. Search basics. For every page: the page title (under 60 characters), the meta description (under 155 characters), the single h1, and the phrase a buyer would actually type to find it. Add which pages should link to which.\n\nUse only the proof listed in the brief. Where a section needs something I have not given you, write [NEEDED: what] and do not fill it in.","prompts":[{"title":"Draw the blueprint","prompt":"Plan the structure of an agency website from this brief:\n\n[paste brief.md]\n\nGive me four things.\n\n1. Site map. Every page, its address (for example /work/client-name), and its one job in a single sentence. Suggest the smallest set of pages that does the brief justice.\n\n2. Visitor journeys. The three most likely ways someone arrives (for example a referral who types the name, a search for the service, a link to one case study), and for each, the pages they see in order and the moment they would enquire.\n\n3. Sections per page. For every page, the sections from top to bottom. For each section, say what question in the visitor''s head it answers. If a section answers no question, remove it.\n\n4. Search basics. For every page: the page title (under 60 characters), the meta description (under 155 characters), the single h1, and the phrase a buyer would actually type to find it. Add which pages should link to which.\n\nUse only the proof listed in the brief. Where a section needs something I have not given you, write [NEEDED: what] and do not fill it in."},{"title":"Cut it down","prompt":"Here is the brief and the blueprint for an agency website:\n\n[paste brief.md]\n\n[paste blueprint.md]\n\nI want to launch sooner. Tell me which pages and sections I can remove without making a buyer less likely to enquire, and which ones I must keep. Give me the trimmed blueprint, and a short list of what I am putting off until version two."}]},{"kind":"checklist","tasks":[{"id":"agency-blueprint-saved","label":"Saved the blueprint as blueprint.md"},{"id":"agency-blueprint-jobs","label":"Every page has one job I can say in a sentence"},{"id":"agency-blueprint-needed","label":"Made a list of everything marked NEEDED"}]}]},{"key":"copy","title":"Copy","intro":"Write the words before anything is designed. A layout built around real sentences needs far less fixing.","blocks":[{"kind":"text","body":"Design made around placeholder text gets redone when the real text arrives, because the real headline is twice as long and the real case study has no photo. Write first.\n\nThe case studies matter most. A buyer skims the home page and reads the work. Each one needs the same four parts: what the client was stuck on, what you did, what changed, and a line from the client."},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Write the copy for an agency website. Here is the brief and the blueprint:\n\n[paste brief.md]\n\n[paste blueprint.md]\n\nGo page by page, section by section, in the order the blueprint gives. For each section write the final words, not a description of them.\n\nRules:\n- Headlines say what the visitor gets, in eight words or fewer. No headline that would fit any other agency.\n- One supporting sentence under each headline, 20 words or fewer.\n- One primary button label, used the same way on every page, that names the action in the brief.\n- Write in the tone the brief asks for. Plain words. No \"we are passionate about\", no \"solutions\", no \"elevate\".\n- Use only the projects, numbers and testimonials in the brief. Where proof is missing, write [NEEDED: what] and move on. Do not invent clients, statistics or quotes.\n- For the contact page, write the form labels, the helper text, the button, the message shown after sending, and the message shown if sending fails.\n- Write six questions and answers a buyer really asks before hiring, including price and timescale.\n- For the footer, list the links and the legal lines the site needs, and tell me which legal pages I must get written properly.\n\nFinish with a list of every [NEEDED] item so I can go and get them.","prompts":[{"title":"Write the copy","prompt":"Write the copy for an agency website. Here is the brief and the blueprint:\n\n[paste brief.md]\n\n[paste blueprint.md]\n\nGo page by page, section by section, in the order the blueprint gives. For each section write the final words, not a description of them.\n\nRules:\n- Headlines say what the visitor gets, in eight words or fewer. No headline that would fit any other agency.\n- One supporting sentence under each headline, 20 words or fewer.\n- One primary button label, used the same way on every page, that names the action in the brief.\n- Write in the tone the brief asks for. Plain words. No \"we are passionate about\", no \"solutions\", no \"elevate\".\n- Use only the projects, numbers and testimonials in the brief. Where proof is missing, write [NEEDED: what] and move on. Do not invent clients, statistics or quotes.\n- For the contact page, write the form labels, the helper text, the button, the message shown after sending, and the message shown if sending fails.\n- Write six questions and answers a buyer really asks before hiring, including price and timescale.\n- For the footer, list the links and the legal lines the site needs, and tell me which legal pages I must get written properly.\n\nFinish with a list of every [NEEDED] item so I can go and get them."},{"title":"Write a case study","prompt":"Turn my notes into a case study for an agency website. The tone is in this brief:\n\n[paste brief.md]\n\nMy notes on the project:\nClient and what they do: [who]\nWhat they were stuck on: [the problem, in their words if you have them]\nWhat we did: [the work, and how long it took]\nWhat changed: [results, with real numbers only]\nWhat the client said: [the exact quote, and whether I have permission to use it]\n\nWrite it in four short parts: the problem, what we did, the result, the quote. Open with the result. Keep it under 350 words. Give me a title, a one-line summary for the Work page, and a description of the one image that would prove the result. If I gave you no number, do not add one. Tell me what to ask the client for."},{"title":"Tighten it","prompt":"Here is the copy for an agency website:\n\n[paste copy.md]\n\nEdit it like a strict editor. Cut every sentence that would be true of any agency. Shorten whatever is left by a third without losing a fact. Flag any claim that has no proof beside it. Show me the edited version, then a list of what you cut and why."}]},{"kind":"callout","tone":"info","body":"A client''s site? Send them copy.md and get it approved before you design anything. Changes to words are free at this point and expensive later, and a signed-off document is what you point to when the feedback starts to wander."},{"kind":"checklist","tasks":[{"id":"agency-copy-saved","label":"Saved the copy as copy.md"},{"id":"agency-copy-cases","label":"Wrote at least two case studies from real projects"},{"id":"agency-copy-needed","label":"No NEEDED markers left, or a date to get each one"}]}]},{"key":"design","title":"Design system","intro":"Choose the colours, type and spacing once, so every page looks like it belongs to the same site.","blocks":[{"kind":"text","body":"A design system is the short list of decisions that every page reuses: a handful of colours, two typefaces, a set of sizes and gaps, and the parts that repeat, such as buttons, cards and the navigation.\n\nAsk for it in a form your build tool can read. Design tokens are those decisions written as named values, for example a colour called primary. Change the value once and the whole site follows."},{"kind":"callout","tone":"tip","body":"Ask only for the parts your blueprint uses. A request for 30 components gets you 30 components, most of which no page needs, and each one is something to keep consistent. A typical agency site needs about a dozen."},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Create a design system for an agency website. The brand already exists, so extend it and do not replace it.\n\nThe brief:\n[paste brief.md]\n\nThe blueprint:\n[paste blueprint.md]\n\nWhat the brand already has: [logo description, colour codes, typefaces, anything from brand guidelines]\n\nProduce:\n1. Colour. The brand colours, plus the neutrals and the success, warning and error colours the site needs. A light and a dark version. For every text and background pair you expect me to use, give the contrast ratio and confirm it meets WCAG AA (4.5 to 1 for body text, 3 to 1 for large text). Change any pair that fails and tell me you did.\n2. Type. The typefaces, where to get them, and a scale of sizes from small print to the largest headline, each with its line height and weight.\n3. Spacing. One scale based on 8 pixels, and the rule for when to use each step.\n4. Layout. Maximum content width, columns and gutters at phone, tablet and desktop widths.\n5. Components. Only the ones the blueprint uses. For each: what it is for, its variants, and how it looks at rest, on hover, when focused with a keyboard, when pressed, when disabled, and when loading or showing an error if that applies.\n6. Motion. Two or three durations and one easing curve, and what each is for.\n\nGive me the result twice: as CSS custom properties I can paste into a stylesheet, and as a written description in plain words that I can paste into a design tool.","prompts":[{"title":"Build it from a brand","prompt":"Create a design system for an agency website. The brand already exists, so extend it and do not replace it.\n\nThe brief:\n[paste brief.md]\n\nThe blueprint:\n[paste blueprint.md]\n\nWhat the brand already has: [logo description, colour codes, typefaces, anything from brand guidelines]\n\nProduce:\n1. Colour. The brand colours, plus the neutrals and the success, warning and error colours the site needs. A light and a dark version. For every text and background pair you expect me to use, give the contrast ratio and confirm it meets WCAG AA (4.5 to 1 for body text, 3 to 1 for large text). Change any pair that fails and tell me you did.\n2. Type. The typefaces, where to get them, and a scale of sizes from small print to the largest headline, each with its line height and weight.\n3. Spacing. One scale based on 8 pixels, and the rule for when to use each step.\n4. Layout. Maximum content width, columns and gutters at phone, tablet and desktop widths.\n5. Components. Only the ones the blueprint uses. For each: what it is for, its variants, and how it looks at rest, on hover, when focused with a keyboard, when pressed, when disabled, and when loading or showing an error if that applies.\n6. Motion. Two or three durations and one easing curve, and what each is for.\n\nGive me the result twice: as CSS custom properties I can paste into a stylesheet, and as a written description in plain words that I can paste into a design tool."},{"title":"Build it from scratch","prompt":"Create a design system for an agency website that has no brand yet.\n\nThe brief:\n[paste brief.md]\n\nThe blueprint:\n[paste blueprint.md]\n\nFirst propose three distinct visual directions that suit the audience and tone in the brief. For each: a name, the feeling in one sentence, a palette of five colours with codes, a pair of freely licensed typefaces, and one existing well-known site it is in the spirit of. Say which you would pick and why. Then stop and wait for me to choose.\n\nWhen I choose, produce the full system: colour in light and dark with contrast ratios checked against WCAG AA, a type scale, an 8 pixel spacing scale, layout widths, only the components the blueprint uses with all their states, and motion values. Give it to me as CSS custom properties and as a plain-words description."},{"title":"Check my contrast","prompt":"Here is the colour part of my design system:\n\n[paste the colours]\n\nList every combination of text colour on background colour I am likely to use, in light and dark mode. For each, give the contrast ratio and whether it passes WCAG AA for body text, for large text, and for the outline of a button or form field. For every failure, suggest the nearest colour that passes."}]},{"kind":"checklist","tasks":[{"id":"agency-design-saved","label":"Saved the system as design-system.md"},{"id":"agency-design-tokens","label":"Have the tokens as CSS custom properties"},{"id":"agency-design-contrast","label":"Every text and background pair passes AA"}]}]},{"key":"behaviour","title":"Behaviour","intro":"Describe how the moving parts work, how the site moves, and how it changes shape on a phone.","blocks":[{"kind":"text","body":"A design shows what the site looks like when everything goes right. This step covers the rest: what the enquiry form does when the email address is wrong, what the Work page shows when a filter matches nothing, how a page settles as it loads, and what happens to a three-column grid on a phone.\n\nThere are three prompts here and you want all three. Save the answers together as behaviour.md."},{"kind":"prompt","label":"1. The interactive parts","prompt":"Describe how the interactive parts of an agency website behave. Here is the blueprint and the copy:\n\n[paste blueprint.md]\n\n[paste copy.md]\n\nFirst list every part of the site that responds to the visitor, such as the enquiry form, any filter on the Work page, the mobile menu, and anything else the blueprint includes. Do not add features the blueprint does not ask for.\n\nThen for each one, describe:\n1. Its states in plain words (for example empty, filling in, checking, sending, sent, failed) and what moves it from one to the next.\n2. What it needs to be given and what it sends out.\n3. The rules for each field, and the exact words shown when a rule is broken.\n4. What the visitor sees while it is loading, when there is nothing to show, and when something fails.\n5. The awkward cases: a double click on send, the connection dropping halfway, the back button, a very long name, JavaScript switched off.\n6. How it works with a keyboard and a screen reader.\n\nWrite each one as a short spec I can hand to a build tool, laid out as React components with their state and event handlers named."},{"kind":"prompt","label":"2. Motion","prompt":"Plan the motion for an agency website. Here is the blueprint and the design system:\n\n[paste blueprint.md]\n\n[paste design-system.md]\n\nUse the durations and easing from the design system. Motion should help the visitor follow what changed, and should never make them wait to read.\n\nCover, page by page: what happens as the page loads, what happens as sections scroll into view, hover and focus feedback on links, buttons and cards, and how menus and any pop-up panels open and close.\n\nWrite each one as a plain sentence a build tool can follow, with numbers. For example: when the page loads, the headline fades in and rises 16 pixels over 400 milliseconds, and the line under it follows 80 milliseconds later.\n\nRules: animate only opacity and transform. Nothing longer than 500 milliseconds. Nothing that hides content until the visitor scrolls. Say exactly what happens for someone whose device is set to reduce motion, which should be that content simply appears.\n\nFinish by naming the three animations that matter most, and telling me which of the rest I could drop without anyone noticing."},{"kind":"prompt","label":"3. Phone, tablet and desktop","prompt":"Plan how an agency website adapts to screen size. Here is the blueprint and the design system:\n\n[paste blueprint.md]\n\n[paste design-system.md]\n\nGive me a table with one row per section of every page, and these columns: Section, Phone (375 pixels wide), Tablet (768), Desktop (1440), Notes.\n\nIn each cell say: how the layout changes (for example three columns become one), the headline and body text sizes, what happens to images (crop, resize, swap or hide), and the padding and gaps.\n\nAfter the table, add:\n1. How the navigation works at each size.\n2. What moves up or down the page on a phone, and why. Nothing a buyer needs should be hidden on a phone.\n3. What happens between the three sizes, especially around 1024 pixels wide, where layouts most often break.\n4. Every button and link is at least 24 by 24 pixels, and 44 where there is room.\n5. What a very wide screen shows, so lines of text never run the full width."},{"kind":"callout","tone":"info","body":"No dashboards, sign-in or price calculators unless the brief asks for them. An agency site rarely needs any of them, and each one adds a week and a new way to break. If you do want a project estimator, add it to the blueprint first, then run prompt 1 again."},{"kind":"checklist","tasks":[{"id":"agency-behaviour-saved","label":"Saved all three answers as behaviour.md"},{"id":"agency-behaviour-form","label":"The enquiry form has words for every error"},{"id":"agency-behaviour-motion","label":"Reduced motion is covered"}]}]},{"key":"data","title":"Forms and content","intro":"Decide where an enquiry goes when someone presses send, and where the case studies live.","blocks":[{"kind":"text","body":"An agency site has very little behind it, and that is a good thing. There are only two questions.\n\nWhere do enquiries go? The simplest answer that works: the form sends an email to the agency''s inbox and shows a thank-you message. Saving each enquiry in a database as well is a sensible backup, so one lost email is not one lost client.\n\nWhere do case studies live? If you will be the one adding them, keep them as files in the project. If the client wants to add their own without calling you, they need a content management system, a CMS, which is a login where they type into a form and the site updates."},{"kind":"callout","tone":"warning","body":"The enquiry form is open to the whole internet. Check every field again on the server, because the checks in the browser can be skipped. Add a spam trap and a limit on how often one visitor can send. Keep the email service key in your host''s environment variables, never in the page or in code you push. And test what the visitor sees when sending fails, because that is when you are losing a real enquiry."},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Plan the back end for an agency website, and keep it as small as it can be. Here is the blueprint and the behaviour spec:\n\n[paste blueprint.md]\n\n[paste behaviour.md]\n\nHow I am building it: [for example Next.js on Vercel, or an app builder, or not decided]\nWho will add case studies after launch: [me, or the client]\n\nCover:\n1. The enquiry form. What happens between pressing send and the agency reading it. Which service sends the email. Whether to store each enquiry too, and where. What the visitor gets back on success and on failure.\n2. Protecting the form. Server-side checks for every field, a spam trap, a rate limit, and where each secret key lives.\n3. Case studies and other content. Where they are stored and how a new one gets published, given who is adding them. If you suggest a CMS, name the fields for a case study.\n4. Speed. What can be built ahead of time and served as plain pages, and what has to run on each visit.\n5. Failure. What the site does if the email service is down, and how the agency would find out.\n6. Personal data. What the form collects, how long it should be kept, and what the privacy page has to say about it.\n\nLeave out sign-in, user accounts, live updates and search unless the blueprint asks for them. For anything you do add, give the reason in one line.","prompts":[{"title":"Plan the back end","prompt":"Plan the back end for an agency website, and keep it as small as it can be. Here is the blueprint and the behaviour spec:\n\n[paste blueprint.md]\n\n[paste behaviour.md]\n\nHow I am building it: [for example Next.js on Vercel, or an app builder, or not decided]\nWho will add case studies after launch: [me, or the client]\n\nCover:\n1. The enquiry form. What happens between pressing send and the agency reading it. Which service sends the email. Whether to store each enquiry too, and where. What the visitor gets back on success and on failure.\n2. Protecting the form. Server-side checks for every field, a spam trap, a rate limit, and where each secret key lives.\n3. Case studies and other content. Where they are stored and how a new one gets published, given who is adding them. If you suggest a CMS, name the fields for a case study.\n4. Speed. What can be built ahead of time and served as plain pages, and what has to run on each visit.\n5. Failure. What the site does if the email service is down, and how the agency would find out.\n6. Personal data. What the form collects, how long it should be kept, and what the privacy page has to say about it.\n\nLeave out sign-in, user accounts, live updates and search unless the blueprint asks for them. For anything you do add, give the reason in one line."},{"title":"Do I need a CMS?","prompt":"I am building an agency website and deciding where the content should live.\n\nWho updates the site after launch: [me, the client, both]\nHow often: [a case study a month, a blog post a week, almost never]\nHow comfortable they are with tools: [describe]\nHow I am building it: [tool or framework]\n\nTell me honestly whether I need a content management system, or whether files in the project would do. If I need one, say what kind and what it will cost each month. If I do not, say what the signs would be that I have outgrown files."}]},{"kind":"links","links":[{"label":"Resend in the directory","href":"/tools/resend"},{"label":"Add a database with Supabase","href":"/walkthroughs/add-a-database-with-supabase"}]},{"kind":"checklist","tasks":[{"id":"agency-data-saved","label":"Saved the plan as data.md"},{"id":"agency-data-enquiry","label":"Know exactly where an enquiry ends up"},{"id":"agency-data-content","label":"Decided who adds case studies, and how"}]}]},{"key":"build","title":"Build","intro":"Turn the spec into the site, one page at a time, and check each page against what you wrote.","blocks":[{"kind":"text","body":"You now have six files that describe the whole site. The build is mostly feeding them to a tool in the right order.\n\nThe mistake to avoid is pasting everything in and asking for the whole site at once. You get something that looks finished and is wrong in forty small ways. Build the home page first, get it right, and let every later page copy it."},{"kind":"tabs","label":"How are you building?","tabs":[{"key":"design-tool","title":"Design tool first","blocks":[{"kind":"text","body":"Best when a client needs to see and approve a design before any code exists. Tools such as Figma Make and Claude Design turn a prompt into a clickable design. Give them the written description of your design system, then one page at a time."},{"kind":"links","links":[{"label":"Figma Make","href":"/tools/figma-make"},{"label":"Claude Design","href":"/tools/claude-design"}]}]},{"key":"app-builder","title":"App builder","blocks":[{"kind":"text","body":"Best when you want a working site quickly and would not choose to touch code. Builders such as Lovable, v0 and Bolt write and host the site from your prompts. Start with the design tokens, then the home page, then ask for each remaining page in the same style."},{"kind":"links","links":[{"label":"Lovable","href":"/tools/lovable"},{"label":"v0","href":"/tools/v0"},{"label":"Bolt","href":"/tools/bolt"}]}]},{"key":"coding-agent","title":"Coding agent","blocks":[{"kind":"text","body":"Best when you want full control and are comfortable in a project folder. Put the spec folder inside your project so the agent can read the files itself, and you can say \"build the Work page from spec/blueprint.md\" with nothing to paste."},{"kind":"links","links":[{"label":"Claude Code","href":"/tools/claude-code"},{"label":"Cursor","href":"/tools/cursor"},{"label":"Next.js","href":"/tools/nextjs"}]}]}]},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Turn my website spec into prompts for a build tool. I am building with: [name the tool].\n\n[paste brief.md]\n[paste blueprint.md]\n[paste copy.md]\n[paste design-system.md]\n[paste behaviour.md]\n[paste data.md]\n\nWrite one prompt per step, in the order I should run them:\n1. Foundations: the design tokens, typefaces, page shell, navigation and footer.\n2. The home page.\n3. One prompt for each remaining page in the blueprint.\n4. The enquiry form, wired up as the data plan describes.\n5. Motion, applied across the pages already built.\n\nEach prompt must:\n- Open with the finished result in one sentence.\n- Carry the exact colours, typefaces and spacing it needs, because the tool will not remember them from an earlier prompt.\n- Name the sections in order, with the real copy for each one.\n- Say how the page behaves at 375, 768 and 1440 pixels wide.\n- Say what happens on hover, focus and click.\n- End with a short list of things I can check by looking, so I know when the step is done.\n\nKeep each prompt short enough for the tool I named. If a page is too big for one prompt, split it and say so.","prompts":[{"title":"Write my build prompts","prompt":"Turn my website spec into prompts for a build tool. I am building with: [name the tool].\n\n[paste brief.md]\n[paste blueprint.md]\n[paste copy.md]\n[paste design-system.md]\n[paste behaviour.md]\n[paste data.md]\n\nWrite one prompt per step, in the order I should run them:\n1. Foundations: the design tokens, typefaces, page shell, navigation and footer.\n2. The home page.\n3. One prompt for each remaining page in the blueprint.\n4. The enquiry form, wired up as the data plan describes.\n5. Motion, applied across the pages already built.\n\nEach prompt must:\n- Open with the finished result in one sentence.\n- Carry the exact colours, typefaces and spacing it needs, because the tool will not remember them from an earlier prompt.\n- Name the sections in order, with the real copy for each one.\n- Say how the page behaves at 375, 768 and 1440 pixels wide.\n- Say what happens on hover, focus and click.\n- End with a short list of things I can check by looking, so I know when the step is done.\n\nKeep each prompt short enough for the tool I named. If a page is too big for one prompt, split it and say so."},{"title":"Check a page against the spec","prompt":"I have built one page of an agency website and want it checked against the spec before I move on.\n\nThe page: [name it]\nWhat I built: [paste the code, or attach screenshots at phone and desktop width]\n\nThe spec for it:\n[paste the relevant parts of blueprint.md, copy.md, design-system.md and behaviour.md]\n\nList every place the page differs from the spec, most noticeable first. For each one, say whether to fix the page or update the spec, and give me the prompt or the change that fixes it. Then tell me anything that matches the spec but still looks or reads wrong."},{"title":"Fix something that looks off","prompt":"One part of my agency website does not look right and I cannot say why.\n\nThe part: [for example the case study cards on the Work page]\nWhat I see: [describe it, or attach a screenshot]\nMy design system:\n[paste design-system.md]\n\nTell me what is off, in designer''s terms and then in plain words: spacing, alignment, size, contrast or rhythm. Give me the exact change to make, using the tokens from my design system and no new values."}]},{"kind":"callout","tone":"tip","body":"After every page, look at it on your actual phone, not only in a narrow browser window. Then tab through it with the keyboard. Those two checks catch most of what a client will complain about."},{"kind":"checklist","tasks":[{"id":"agency-build-home","label":"Built the home page and checked it against the spec"},{"id":"agency-build-pages","label":"Built every other page in the blueprint"},{"id":"agency-build-form","label":"Sent a test enquiry and saw it arrive"},{"id":"agency-build-phone","label":"Checked every page on a real phone"}]}]},{"key":"launch","title":"Launch","intro":"Test the real site, fix what matters, put it on its domain, and hand it over properly.","blocks":[{"kind":"text","body":"Audit the site you built, not the plan for it. A spec cannot be slow, and a live page can.\n\n1. Put the site on a preview link from your host.\n2. Open pagespeed.web.dev, paste in the link, and run it for the home page and one case study. Keep the results.\n3. Send a real enquiry through the form from your phone. Then send one with a wrong email address, and one with the wifi switched off.\n4. Go through every page using only the Tab and Enter keys."},{"kind":"links","links":[{"label":"Open PageSpeed Insights","href":"https://pagespeed.web.dev"}]},{"kind":"prompt","label":"Pick a prompt and paste it into your AI tool","prompt":"Audit an agency website before it goes live. Work from the evidence below. Where you cannot check something from what I have given you, do not guess. Add it to a list of things I must test by hand, with the steps.\n\nThe preview link: [paste it]\nPageSpeed Insights results for the home page and one case study: [paste them]\nHow it is built and hosted: [tool or framework, and host]\nWhat happened when I tested the form: [describe it]\nThe code, if I have it: [paste the main files, or say the tool hides it]\n\nCheck:\n- Speed: the largest element appears within 2.5 seconds, the page responds to a tap within 200 milliseconds, and the layout shifts by less than 0.1.\n- Accessibility to WCAG 2.2 AA: contrast, keyboard use, visible focus, headings in order, text alternatives for images, labels and error messages on the form.\n- Search: a unique title and description on every page, one h1, a sitemap, structured data for the organisation, a sharing image, and nothing blocking search engines by mistake.\n- Security: HTTPS everywhere, security headers, form input checked on the server, no secret keys in the page.\n- Browsers: Chrome, Safari, Firefox and Edge, and Safari on an iPhone in particular.\n- Phone: tap targets, text size, no sideways scrolling.\n- Analytics: whether a sent enquiry is recorded as a goal, and whether the site needs a cookie notice for the tools it loads.\n- Content: no placeholder text, no [NEEDED] markers, no broken links, a real privacy page.\n\nFor every finding give: how serious it is (critical, high, medium or low), exactly where it is, what is wrong, and the fix. Put them in the order I should fix them. Critical means I should not launch until it is done.","prompts":[{"title":"Audit before launch","prompt":"Audit an agency website before it goes live. Work from the evidence below. Where you cannot check something from what I have given you, do not guess. Add it to a list of things I must test by hand, with the steps.\n\nThe preview link: [paste it]\nPageSpeed Insights results for the home page and one case study: [paste them]\nHow it is built and hosted: [tool or framework, and host]\nWhat happened when I tested the form: [describe it]\nThe code, if I have it: [paste the main files, or say the tool hides it]\n\nCheck:\n- Speed: the largest element appears within 2.5 seconds, the page responds to a tap within 200 milliseconds, and the layout shifts by less than 0.1.\n- Accessibility to WCAG 2.2 AA: contrast, keyboard use, visible focus, headings in order, text alternatives for images, labels and error messages on the form.\n- Search: a unique title and description on every page, one h1, a sitemap, structured data for the organisation, a sharing image, and nothing blocking search engines by mistake.\n- Security: HTTPS everywhere, security headers, form input checked on the server, no secret keys in the page.\n- Browsers: Chrome, Safari, Firefox and Edge, and Safari on an iPhone in particular.\n- Phone: tap targets, text size, no sideways scrolling.\n- Analytics: whether a sent enquiry is recorded as a goal, and whether the site needs a cookie notice for the tools it loads.\n- Content: no placeholder text, no [NEEDED] markers, no broken links, a real privacy page.\n\nFor every finding give: how serious it is (critical, high, medium or low), exactly where it is, what is wrong, and the fix. Put them in the order I should fix them. Critical means I should not launch until it is done."},{"title":"Fix a finding","prompt":"My pre-launch audit found this problem on my agency website:\n\n[paste the finding]\n\nHow the site is built: [tool or framework]\nThe part of the code or page involved: [paste it or describe it]\n\nExplain what is wrong in plain words, give me the exact change, and tell me how to check that it worked."},{"title":"Write the handover","prompt":"I have finished an agency website for a client and need to hand it over.\n\nHow it is built and hosted: [details]\nThe accounts involved: [domain, hosting, email service, content system, analytics]\nWhat the client will do themselves: [for example add case studies]\nWhat I will keep doing, if anything: [for example monthly updates]\n\nWrite a handover document the client can follow without me. Include: every account and who owns it, how to add a case study step by step, how to change a piece of text, where enquiries arrive and what to do if they stop, what needs renewing and when, and who to contact for what. Use plain words and no jargon. Then write a short email to send with it."}]},{"kind":"tabs","label":"Whose site is it?","tabs":[{"key":"mine","title":"My own agency","blocks":[{"kind":"text","body":"1. Point your domain at the site, then check that the address without www and the address with it both arrive at the same place.\n2. If you are replacing an old site, redirect its old addresses to the new pages, so links and search results keep working.\n3. Add the site to Google Search Console and submit the sitemap.\n4. Put a date in your calendar to add a case study every time you finish a project. An agency site with nothing new for a year tells buyers the wrong thing."}]},{"key":"client","title":"A client''s agency","blocks":[{"kind":"text","body":"1. The domain, the hosting, the email service and the analytics should be in accounts the client owns, with you invited in. Not the other way round. If you set them up under your name to move quickly, transfer them before you send the final invoice.\n2. Get sign-off in writing against the brief and the approved copy.\n3. Redirect the old site''s addresses to the new pages.\n4. Send the handover document, then walk the client through adding one case study on a call while they do the clicking.\n5. Agree what happens next: who fixes things, how fast, and what it costs."}]}]},{"kind":"callout","tone":"tip","body":"Send yourself an enquiry through the live site, on its real domain, the day it launches and again a week later. A form that quietly stopped working is the most expensive fault an agency site can have, and nobody tells you about it."},{"kind":"checklist","tasks":[{"id":"agency-launch-audit","label":"Ran the audit and fixed everything critical and high"},{"id":"agency-launch-domain","label":"Site is live on its own domain"},{"id":"agency-launch-enquiry","label":"Sent a test enquiry on the live domain and it arrived"},{"id":"agency-launch-handover","label":"Handed over, or set a reminder to add the next case study"}]}]}]'::jsonb
)
on conflict (slug) do update set
  title      = excluded.title,
  kind       = excluded.kind,
  role_level = excluded.role_level,
  status     = excluded.status,
  steps      = excluded.steps,
  updated_at = now();

insert into wizard_recommended_tools (wizard_id, tool_id)
select w.id, t.id
from wizards w
join tools t on t.slug in ('claude', 'figma-make', 'claude-design', 'lovable', 'v0', 'claude-code', 'nextjs', 'vercel', 'resend')
where w.slug = 'build-an-agency-website'
on conflict do nothing;
